# patch_20261010_country_select_unify.ps1
# Every country control in URM reads app.countries through ONE shared component
# (src/components/common/country-select.tsx). 7 files changed, 2 added, 1 removed.
# Writes nothing unless EVERY file still matches the reviewed original
# (LF-normalized SHA-256). Idempotent. ASCII output only.
$Repo = "C:\dev\mbg-project"
function Sha([string]$t) { $b = [System.Text.Encoding]::UTF8.GetBytes($t); $h = [System.Security.Cryptography.SHA256]::Create().ComputeHash($b); ($h | ForEach-Object { $_.ToString("x2") }) -join "" }
$items = @(
  @{ Path = "src\app\(app)\marketing\marketing-client.tsx"; Old = "7a93e0e9c2bfadbd0bddd3752432ebd0f1a833422502bc8148ad6e84f1375293"; New = "ca409b81b770824add112e8ec28418663bad181e929fd51db6df3b025884f74b"; B64 = "" },
  @{ Path = "src\components\parties\country-filter-bar.tsx"; Old = "f8018699b094859c480a73995540a594b524930f267658b35c4cec86c01f0d84"; New = "2bcc5ce9ce5d87805ec08386194bded8e66064f4b608c99ec62268bffbd8795b"; B64 = "" },
  @{ Path = "src\components\parties\inline-party-create-dialog.tsx"; Old = "66d833bb9a03478ba70e02f7c162581febf382a388233d369032d2e2e56869a4"; New = "dfa7eced0a6cafb64cde1c417356cccc6b859743bc3ed18724a2c1846234d62e"; B64 = "" },
  @{ Path = "src\components\parties\parties-filter-bar.tsx"; Old = "ae9579b9ccf7e1ac002918f453bfed6e235683229bf462499a1fc8a83fe725ac"; New = "47a887e4d2b0dd9d067f986ccebee193216303b120815c022b24a18bea4ca17a"; B64 = "" },
  @{ Path = "src\components\parties\party-form.tsx"; Old = "5e2faa6eaa5c511ffb878e18c91b86f34c2cc7d104c54f1573409471af3d0ec7"; New = "0592cb58b888b810b774a303ae55b589ea3085db59a9f908effbdef7b6d07d89"; B64 = "" },
  @{ Path = "src\components\settings\bulk-enroll-dialog.tsx"; Old = "ee52c6f704ccdc744c4fd5e06377fa6b6ce24a8fe5d4fc9734c346231b6627d1"; New = "a35ded8110c31316a7c3c67f27241684ae38116b802c157f0c3447f2b7bff185"; B64 = "" },
  @{ Path = "src\lib\constants\countries.ts"; Old = "22486b896e7aa9b8dbefe6024d0a2591c59d1f4dcad420555f94045498b781e2"; New = "b3f6c1141a907d88ab3bbb98a9188d33b655312161241b558d14425a29b95759"; B64 = "" },
  @{ Path = "src\components\common\country-select.tsx"; Old = "ABSENT"; New = "67cf61123dd596a3962e02c5f45c70d077435d3625fa48ccd0b01eb99a3940d1"; B64 = "" },
  @{ Path = "src\lib\actions\countries.ts"; Old = "ABSENT"; New = "ad983cc419899daed6d6bf7a7a44191201dd93c53510fe3a121de41a67acbdc3"; B64 = "" },
  @{ Path = "src\components\marketing\country-multi-select.tsx"; Old = "db360a84db9d30ab69cfcb670694c8ddb1178091ee3110ceedb8858590738392"; New = "DELETED"; B64 = "" }
)
foreach ($it in $items) {
  $p = Join-Path $Repo $it.Path
  $exists = Test-Path -LiteralPath $p
  if (-not $exists) { if ($it.Old -eq "ABSENT" -or $it.New -eq "DELETED") { continue }; Write-Output ("ERROR missing " + $it.Path); return }
  $cur = Sha ([System.IO.File]::ReadAllText($p).Replace("`r`n", "`n"))
  if ($cur -ne $it.Old -and $cur -ne $it.New) { Write-Output ("ERROR changed since review, not patched: " + $it.Path); return }
}
foreach ($it in $items) {
  $p = Join-Path $Repo $it.Path
  $exists = Test-Path -LiteralPath $p
  if ($it.New -eq "DELETED") {
    if ($exists) { Remove-Item -LiteralPath $p -Force; Write-Output ("DELETED " + $it.Path) } else { Write-Output ("SKIP  already removed " + $it.Path) }
    $dir = Split-Path -LiteralPath $p
    if ((Test-Path -LiteralPath $dir) -and -not (Get-ChildItem -LiteralPath $dir -Force)) { Remove-Item -LiteralPath $dir -Force }
    continue
  }
  if ($exists) {
    $cur = Sha ([System.IO.File]::ReadAllText($p).Replace("`r`n", "`n"))
    if ($cur -eq $it.New) { Write-Output ("SKIP  already patched " + $it.Path); continue }
  } else { [System.IO.Directory]::CreateDirectory((Split-Path -LiteralPath $p)) | Out-Null }
  [System.IO.File]::WriteAllBytes($p, [System.Convert]::FromBase64String($it.B64))
  Write-Output ("PATCHED " + $it.Path)
}
